    tomasa: L('Tomasa', 'Tomasa', 'Tomasa', 'Tomasa', '[托玛莎|Tuō mǎ shā]', 'トマサ'),
    polo: L('Polo', 'Polo', 'Polo', 'Polo', '[波洛|Bō luò]', 'ポロ'),
